    assign word[27] = (en & (lw == 3'd5) ? (kk == 5'd0) : (lw == 3'd4) ? (kk == 5'd1) : (lw == 3'd3) ? (kk == 5'd3) : (lw == 3'd2) ? (kk == 5'd6) : (lw == 3'd1) ? (kk == 5'd13) : (kk == 5'd27)) ? (lw == 3'd5) ? wd[27] : (lw == 3'd4) ? wd[11] : (lw == 3'd3) ? wd[3] : (lw == 3'd2) ? wd[3] : (lw == 3'd1) ? wd[1] : wd[0] : acc[27];
    assign word[28] = (en & (lw == 3'd5) ? (kk == 5'd0) : (lw == 3'd4) ? (kk == 5'd1) : (lw == 3'd3) ? (kk == 5'd3) : (lw == 3'd2) ? (kk == 5'd7) : (lw == 3'd1) ? (kk == 5'd14) : (kk == 5'd28)) ? (lw == 3'd5) ? wd[28] : (lw == 3'd4) ? wd[12] : (lw == 3'd3) ? wd[4] : (lw == 3'd2) ? wd[0] : (lw == 3'd1) ? wd[0] : wd[0] : acc[28];
    assign word[29] = (en & (lw == 3'd5) ? (kk == 5'd0) : (lw == 3'd4) ? (kk == 5'd1) : (lw == 3'd3) ? (kk == 5'd3) : (lw == 3'd2) ? (kk == 5'd7) : (lw == 3'd1) ? (kk == 5'd14) : (kk == 5'd29)) ? (lw == 3'd5) ? wd[29] : (lw == 3'd4) ? wd[13] : (lw == 3'd3) ? wd[5] : (lw == 3'd2) ? wd[1] : (lw == 3'd1) ? wd[1] : wd[0] : acc[29];
    assign word[30] = (en & (lw == 3'd5) ? (kk == 5'd0) : (lw == 3'd4) ? (kk == 5'd1) : (lw == 3'd3) ? (kk == 5'd3) : (lw == 3'd2) ? (kk == 5'd7) : (lw == 3'd1) ? (kk == 5'd15) : (kk == 5'd30)) ? (lw == 3'd5) ? wd[30] : (lw == 3'd4) ? wd[14] : (lw == 3'd3) ? wd[6] : (lw == 3'd2) ? wd[2] : (lw == 3'd1) ? wd[0] : wd[0] : acc[30];
    assign word[31] = (en & (lw == 3'd5) ? (kk == 5'd0) : (lw == 3'd4) ? (kk == 5'd1) : (lw == 3'd3) ? (kk == 5'd3) : (lw == 3'd2) ? (kk == 5'd7) : (lw == 3'd1) ? (kk == 5'd15) : (kk == 5'd31)) ? (lw == 3'd5) ? wd[31] : (lw == 3'd4) ? wd[15] : (lw == 3'd3) ? wd[7] : (lw == 3'd2) ? wd[3] : (lw == 3'd1) ? wd[1] : wd[0] : acc[31];
    always @(posedge clk) begin
        if (rst) begin cnt <= 5'd0; acc <= 32'd0; end
        else if (en) begin acc <= word; cnt <= flush ? 5'd0 : cnt + 5'd1; end
    end
endmodule

module uc_unity32 (
    input  wire              clk,
    input  wire              rst,
    input  wire [2:0]        lw,
    input  wire              start,
    input  wire [31:0]       entry,
    input  wire              ce,
    input  wire              abort,
    input  wire              dblk,           // a data store is blocked (region check of the slice): it is not accumulated
    output wire              halted,
    output wire              trap,
    output wire              fetching,
    output wire              dmem_act,
    output wire              dmem_ld,
    output wire              dmem_mis,       // v11: a halfword load of an odd address is live (lh / lhu, address bit 0 set)
    output wire              dmem_nar,       // v10: the load live now is a byte or halfword load
    output wire [29:0]       imem_addr,
    input  wire [31:0]       imem_data,
    // register file: whole words, two read ports, one word write port
    output wire [4:0]        ra_wa,
    input  wire [31:0]       ra_word,
    output wire [4:0]        rb_wa,
    input  wire [31:0]       rb_word,
    output wire              rw_we,
    output wire [4:0]        rw_wa,
    output wire [31:0]       rw_word,
    // data memory: whole words
    output wire [29:0]       d_wa,
    input  wire [31:0]       d_word,
    output wire              d_wwe,
    output wire [31:0]       d_wword
);
    wire [9:0]  ra_addr, rb_addr, rw_addr;
    wire [31:0] ra_data, rb_data, rw_data, d_wdata, d_rdata;
    wire        rw_en, d_we;
    wire [34:0] d_addr;
    wire [2:0] ld_nar; wire [1:0] ld_off;
    assign dmem_nar = ld_nar[0];
    assign dmem_mis = ld_nar[1] & ld_off[0];
    uc_unitm32 core (.clk(clk), .rst(rst), .lw(lw), .start(start), .entry(entry), .ce(ce), .abort(abort), .halted(halted), .trap(trap), .fetching(fetching), .dmem_act(dmem_act), .dmem_ld(dmem_ld), .ld_nar(ld_nar), .ld_off(ld_off), .imem_addr(imem_addr), .imem_data(imem_data),
        .ra_addr(ra_addr), .ra_data(ra_data), .rb_addr(rb_addr), .rb_data(rb_data),
        .rw_en(rw_en), .rw_addr(rw_addr), .rw_data(rw_data),
        .d_addr(d_addr), .d_we(d_we), .d_wdata(d_wdata), .d_rdata(d_rdata));
    wire [7:0]  n_b   = ld_off[1] ? (ld_off[0] ? d_word[31:24] : d_word[23:16]) : (ld_off[0] ? d_word[15:8] : d_word[7:0]);
    wire [15:0] n_h   = ld_off[1] ? d_word[31:16] : d_word[15:0];
    wire [31:0] d_ext = !ld_nar[0] ? d_word : ld_nar[1] ? {{16{~ld_nar[2] & n_h[15]}}, n_h} : {{24{~ld_nar[2] & n_b[7]}}, n_b};
    assign ra_wa = ra_addr[9:5]; assign rb_wa = rb_addr[9:5];
    sc_rdsel32 sa (.w(ra_word), .kk(ra_addr[4:0]), .lw(lw), .d(ra_data));
    sc_rdsel32 sb (.w(rb_word), .kk(rb_addr[4:0]), .lw(lw), .d(rb_data));
    sc_rdsel32 sd (.w(d_ext),   .kk(d_addr[4:0]),  .lw(lw), .d(d_rdata));
    assign rw_wa = rw_addr[9:5];
    assign d_wa  = d_addr[34:5];
    sc_wacc32 wr (.clk(clk), .rst(rst | start), .lw(lw), .en(rw_en & ce), .kk(rw_addr[4:0]), .wd(rw_data), .flush(rw_we), .word(rw_word));
    sc_wacc32 wd (.clk(clk), .rst(rst | start), .lw(lw), .en(d_we & ce & ~dblk),  .kk(d_addr[4:0]),  .wd(d_wdata), .flush(d_wwe), .word(d_wword));
endmodule
